BEGIN;
CREATE TABLE nearyou.product_readiness_evidence(evidence_digest text NOT NULL REFERENCES nearyou.release_evidence_audit(claims_digest),product text NOT NULL CHECK(product IN('nearstory','nearfamily','nearlegacy')),release_id text NOT NULL,canonical_product jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT statement_timestamp(),PRIMARY KEY(evidence_digest,product));
REVOKE ALL ON nearyou.product_readiness_evidence FROM PUBLIC,nearyou_app,nearyou_release_verifier;
CREATE OR REPLACE FUNCTION nearyou.consume_release_and_readiness(p_nonce text,p_digest text,p_claims text,p_principal text,p_key_id text,p_key_version integer,p_release text,p_expires timestamptz) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ DECLARE consumed boolean; signed_claims jsonb; item jsonb; existing jsonb; BEGIN IF encode(digest(convert_to(p_claims,'UTF8'),'sha256'),'hex')<>p_digest THEN RAISE EXCEPTION 'claims digest mismatch'; END IF; SELECT nearyou.consume_release_evidence(p_nonce,p_digest,p_claims,p_principal,p_key_id,p_key_version,p_release,p_expires) INTO consumed; IF NOT consumed THEN RETURN false; END IF; SELECT claims_projection INTO signed_claims FROM nearyou.release_evidence_audit WHERE claims_digest=p_digest AND release_id=p_release AND principal=p_principal AND key_id=p_key_id AND key_version=p_key_version; IF jsonb_typeof(signed_claims->'productReadiness')<>'array' OR jsonb_array_length(signed_claims->'productReadiness')<>3 THEN RAISE EXCEPTION 'signed readiness missing'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(signed_claims->'productReadiness') LOOP IF item->>'releaseId'<>p_release OR item->>'environment'<>'production' OR item->>'product' NOT IN('nearstory','nearfamily','nearlegacy') OR (item->>'expiresAt')::bigint<=floor(extract(epoch FROM statement_timestamp())*1000) THEN RAISE EXCEPTION 'signed readiness invalid'; END IF; SELECT canonical_product INTO existing FROM nearyou.product_readiness_evidence WHERE evidence_digest=p_digest AND product=item->>'product'; IF existing IS NOT NULL AND existing<>item THEN RAISE EXCEPTION 'signed readiness replay conflict'; END IF; INSERT INTO nearyou.product_readiness_evidence(evidence_digest,product,release_id,canonical_product,expires_at) VALUES(p_digest,item->>'product',p_release,item,to_timestamp((item->>'expiresAt')::double precision/1000)) ON CONFLICT DO NOTHING; END LOOP; RETURN true; END $$;
ALTER FUNCTION nearyou.consume_release_and_readiness(text,text,text,text,text,integer,text,timestamptz) OWNER TO nearyou_release_policy_owner;
REVOKE ALL ON FUNCTION nearyou.consume_release_and_readiness(text,text,text,text,text,integer,text,timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION nearyou.consume_release_and_readiness(text,text,text,text,text,integer,text,timestamptz) TO nearyou_release_verifier;
CREATE TABLE nearyou.product_rollout_state(product text PRIMARY KEY CHECK(product IN('nearstory','nearfamily','nearlegacy')),mode text NOT NULL CHECK(mode IN('off','canary','percent')),percent integer NOT NULL CHECK(percent BETWEEN 0 AND 100),release_id text,evidence_digest text,version bigint NOT NULL DEFAULT 1,kill_switch boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT statement_timestamp());
INSERT INTO nearyou.product_rollout_state(product,mode,percent) VALUES('nearstory','off',0),('nearfamily','off',0),('nearlegacy','off',0);
CREATE TABLE nearyou.product_rollout_audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,product text NOT NULL,prior_version bigint NOT NULL,new_version bigint NOT NULL,prior_mode text NOT NULL,new_mode text NOT NULL,percent integer NOT NULL,release_id text,evidence_digest text,principal text NOT NULL,created_at timestamptz NOT NULL DEFAULT statement_timestamp());
CREATE TABLE nearyou.product_canary_invites(product text NOT NULL,household_hash text NOT NULL,release_id text NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(product,household_hash,release_id));
ALTER TABLE nearyou.product_readiness_evidence OWNER TO nearyou_release_policy_owner;
ALTER TABLE nearyou.product_rollout_state OWNER TO nearyou_release_policy_owner;
ALTER TABLE nearyou.product_rollout_audit OWNER TO nearyou_release_policy_owner;
ALTER TABLE nearyou.product_canary_invites OWNER TO nearyou_release_policy_owner;
ALTER SEQUENCE nearyou.product_rollout_audit_id_seq OWNER TO nearyou_release_policy_owner;
CREATE FUNCTION nearyou.reject_product_audit_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'product rollout audit immutable'; END $$;
CREATE TRIGGER product_rollout_audit_immutable BEFORE UPDATE OR DELETE ON nearyou.product_rollout_audit FOR EACH ROW EXECUTE FUNCTION nearyou.reject_product_audit_mutation();
REVOKE ALL ON nearyou.product_rollout_state,nearyou.product_rollout_audit,nearyou.product_canary_invites FROM PUBLIC,nearyou_app;
CREATE ROLE nearyou_rollout_controller NOLOGIN NOINHERIT NOBYPASSRLS;
CREATE TABLE nearyou.rollout_controller_identities(database_user name NOT NULL,principal text NOT NULL CHECK(principal~'^service:[A-Za-z0-9_-]{3,100}$'),PRIMARY KEY(database_user,principal));
ALTER TABLE nearyou.rollout_controller_identities OWNER TO nearyou_release_policy_owner;
REVOKE ALL ON nearyou.rollout_controller_identities FROM PUBLIC,nearyou_app,nearyou_release_verifier,nearyou_rollout_controller;
CREATE FUNCTION nearyou.register_rollout_controller_identity(p_database_user name,p_principal text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ BEGIN IF current_user<>'nearyou_release_policy_owner' OR p_database_user::text!~'^[A-Za-z0-9_.@-]{3,200}$' OR p_principal!~'^service:[A-Za-z0-9_-]{3,100}$' OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=p_database_user::text) OR NOT pg_has_role(p_database_user,'nearyou_rollout_controller','MEMBER') THEN RAISE EXCEPTION 'rollout controller identity invalid'; END IF; INSERT INTO nearyou.rollout_controller_identities VALUES(p_database_user,p_principal) ON CONFLICT DO NOTHING; END $$;
ALTER FUNCTION nearyou.register_rollout_controller_identity(name,text) OWNER TO nearyou_release_policy_owner;
REVOKE ALL ON FUNCTION nearyou.register_rollout_controller_identity(name,text) FROM PUBLIC,nearyou_app,nearyou_release_verifier,nearyou_rollout_controller;
GRANT EXECUTE ON FUNCTION nearyou.register_rollout_controller_identity(name,text) TO nearyou_migration;
CREATE FUNCTION nearyou.transition_product_rollout(p_product text,p_expected_version bigint,p_mode text,p_percent integer,p_release text,p_digest text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ DECLARE s nearyou.product_rollout_state%ROWTYPE; next_version bigint; actor text:=current_setting('nearyou.principal',true); BEGIN IF actor !~ '^service:[A-Za-z0-9_-]{3,100}$' OR NOT EXISTS(SELECT 1 FROM nearyou.rollout_controller_identities i WHERE i.database_user=session_user AND i.principal=actor) THEN RAISE EXCEPTION 'rollout principal missing'; END IF; SELECT * INTO s FROM nearyou.product_rollout_state WHERE product=p_product FOR UPDATE; IF s.version<>p_expected_version THEN RAISE EXCEPTION 'rollout version conflict'; END IF; IF p_mode='off' THEN p_percent:=0; ELSIF p_release IS NULL OR p_digest IS NULL OR NOT EXISTS(SELECT 1 FROM nearyou.product_readiness_evidence e WHERE e.product=p_product AND e.release_id=p_release AND e.evidence_digest=p_digest AND e.expires_at>statement_timestamp() AND (e.canonical_product->'capacity'->>'soakEndedAt')::bigint-(e.canonical_product->'capacity'->>'soakStartedAt')::bigint>=3600000) THEN RAISE EXCEPTION 'rollout evidence invalid'; ELSIF NOT ((s.mode='off' AND p_mode='canary' AND p_percent=1) OR (s.mode='canary' AND p_mode='percent' AND p_percent BETWEEN 1 AND 100) OR (s.mode='percent' AND p_mode='percent' AND p_percent>=s.percent)) THEN RAISE EXCEPTION 'rollout transition invalid'; END IF; next_version:=s.version+1; UPDATE nearyou.product_rollout_state SET mode=p_mode,percent=p_percent,release_id=p_release,evidence_digest=p_digest,version=next_version,kill_switch=(p_mode='off'),updated_at=statement_timestamp() WHERE product=p_product; INSERT INTO nearyou.product_rollout_audit(product,prior_version,new_version,prior_mode,new_mode,percent,release_id,evidence_digest,principal) VALUES(p_product,s.version,next_version,s.mode,p_mode,p_percent,p_release,p_digest,actor); RETURN next_version; END $$;
REVOKE ALL ON FUNCTION nearyou.transition_product_rollout(text,bigint,text,integer,text,text) FROM PUBLIC,nearyou_release_verifier;
GRANT EXECUTE ON FUNCTION nearyou.transition_product_rollout(text,bigint,text,integer,text,text) TO nearyou_rollout_controller;
CREATE FUNCTION nearyou.upsert_product_canary_invite(p_product text,p_household_hash text,p_release text,p_expires timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ DECLARE actor text:=current_setting('nearyou.principal',true); BEGIN
 IF p_product NOT IN('nearstory','nearfamily','nearlegacy') OR p_household_hash !~ '^[a-f0-9]{64}$' OR p_release !~ '^rel_[A-Za-z0-9_-]{8,100}$' OR p_expires<=statement_timestamp() OR p_expires>statement_timestamp()+interval '30 days' OR actor !~ '^service:[A-Za-z0-9_-]{3,100}$' OR NOT EXISTS(SELECT 1 FROM nearyou.rollout_controller_identities i WHERE i.database_user=session_user AND i.principal=actor) THEN RAISE EXCEPTION 'canary invite invalid'; END IF;
 IF NOT EXISTS(SELECT 1 FROM nearyou.product_rollout_state s WHERE s.product=p_product AND s.mode='canary' AND NOT s.kill_switch AND s.release_id=p_release) THEN RAISE EXCEPTION 'canary rollout inactive'; END IF;
 INSERT INTO nearyou.product_canary_invites(product,household_hash,release_id,expires_at) VALUES(p_product,p_household_hash,p_release,p_expires) ON CONFLICT(product,household_hash,release_id) DO UPDATE SET expires_at=GREATEST(nearyou.product_canary_invites.expires_at,EXCLUDED.expires_at);
 INSERT INTO nearyou.product_rollout_audit(product,prior_version,new_version,prior_mode,new_mode,percent,release_id,evidence_digest,principal) SELECT s.product,s.version,s.version,s.mode,s.mode,s.percent,s.release_id,s.evidence_digest,actor FROM nearyou.product_rollout_state s WHERE s.product=p_product;
END $$;
REVOKE ALL ON FUNCTION nearyou.upsert_product_canary_invite(text,text,text,timestamptz) FROM PUBLIC,nearyou_release_verifier;
GRANT EXECUTE ON FUNCTION nearyou.upsert_product_canary_invite(text,text,text,timestamptz) TO nearyou_rollout_controller;
CREATE FUNCTION nearyou.authorize_product_household(p_product text,p_release text,p_household_hash text,p_cohort integer) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,nearyou AS $$ DECLARE s nearyou.product_rollout_state%ROWTYPE; BEGIN
 IF p_product NOT IN('nearstory','nearfamily','nearlegacy') OR p_release !~ '^rel_[A-Za-z0-9_-]{8,100}$' OR p_household_hash !~ '^[a-f0-9]{64}$' OR p_cohort<0 OR p_cohort>99 THEN RETURN false; END IF;
 SELECT * INTO s FROM nearyou.product_rollout_state WHERE product=p_product;
 IF s.kill_switch OR s.mode='off' OR s.release_id<>p_release OR s.evidence_digest IS NULL OR NOT EXISTS(SELECT 1 FROM nearyou.product_readiness_evidence e WHERE e.product=s.product AND e.release_id=s.release_id AND e.evidence_digest=s.evidence_digest AND e.expires_at>statement_timestamp()) THEN RETURN false; END IF;
 IF s.mode='canary' THEN RETURN EXISTS(SELECT 1 FROM nearyou.product_canary_invites i WHERE i.product=s.product AND i.release_id=s.release_id AND i.household_hash=p_household_hash AND statement_timestamp() < i.expires_at); END IF;
 RETURN p_cohort < s.percent;
END $$;
REVOKE ALL ON FUNCTION nearyou.authorize_product_household(text,text,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION nearyou.authorize_product_household(text,text,text,integer) TO nearyou_app;
COMMIT;
